41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const SWORD_BASE_PREMIUM = 100;
45	
46	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
47	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
48	
49	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
50	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
51	
52	const premiumFor = (items: Item[]): number => {
53	  const basePremium = items.length * SWORD_BASE_PREMIUM;
54	  return roundUpToWholeG(basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
55	};
56	
57	export const runScenario = (scenario: Scenario): ScenarioResult => ({
58	  results: scenario.steps.map((step) => ({
59	    premium: premiumFor((step as QuoteStep).items),
60	  })),
61	});
