const SWORD_BASE_PREMIUM = 100;

/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));

/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));

/** Only the sword's price is pinned down by the tests so far; other types follow. */
const basePremiumFor = (_item: Item): number => SWORD_BASE_PREMIUM;

const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);

const premiumFor = (items: Item[]): number => {
  const basePremium = sum(items.map(basePremiumFor));
  return roundUpToWholeG(basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
};
